-- HR Dataset (Kaggle: HRDataset_v14, ข้อมูลสมมติ) | 311 พนักงาน
-- ตัดชื่อพนักงานและคอลัมน์ที่ไม่จำเป็นออก, แปลงวันที่เป็นรูปแบบ YYYY-MM-DD
DROP TABLE IF EXISTS employees;
CREATE TABLE employees (
  emp_id INTEGER, department TEXT, position TEXT, manager_name TEXT, state TEXT, sex TEXT,
  dob TEXT, hire_date TEXT, term_date TEXT, term_reason TEXT, employment_status TEXT, termd INTEGER,
  salary INTEGER, recruitment_source TEXT, performance_score TEXT, engagement_score REAL,
  satisfaction INTEGER, special_projects INTEGER, days_late_30 INTEGER, absences INTEGER, last_review_date TEXT
);




